import { BLOCKS, MIN_Y, MAX_Y } from "./data.js";
// Sample loaded voxels only. Lava and fire remain audible underground; no new
// terrain is generated by an ambient sound query.
export function surfaceSoundLevels(world, p) {
  let lava = 0,
    fire = 0,
    water = 0;
  if (!world.chunks?.get) return { lava, fire, water };
  for (const [dx, dz] of [
    [0, 0],
    [2, 0],
    [-2, 0],
    [0, 2],
    [0, -2],
    [5, 0],
    [-5, 0],
    [0, 5],
    [0, -5],
  ]) {
    const x = Math.floor(p.x + dx),
      z = Math.floor(p.z + dz),
      cx = Math.floor(x / 16),
      cz = Math.floor(z / 16),
      c = world.chunks.get(`${cx},${cz}`);
    if (!c) continue;
    for (const dy of [-2, -1, 0, 1]) {
      const y = Math.floor(p.y) + dy;
      if (y < MIN_Y || y > MAX_Y) continue;
      const b =
          BLOCKS[c.data[(y - MIN_Y) * 256 + (z - cz * 16) * 16 + x - cx * 16]],
        gain = Math.max(0, 1 - Math.hypot(dx, dy, dz) / 8);
      if (b?.fluid?.type === "lava") lava = Math.max(lava, gain);
      if (b?.fluid?.type === "water") water = Math.max(water, gain);
      if (b?.key === "fire") fire = Math.max(fire, gain);
    }
  }
  return { lava, fire, water };
}
